<?php
require_once __DIR__.'/includes/module.php'; require_roles(['admin','admin_umum']);$page_title='Stok Barang';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{if($action==='new'){$name=trim($_POST['name']??'');if(!$name)throw new RuntimeException();$q=$pdo->prepare('INSERT INTO inventory_items(item_code,name,category,unit,quantity,min_quantity,location,notes) VALUES(?,?,?,?,?,?,?,?)');$q->execute([trim($_POST['item_code']??'')?:null,$name,trim($_POST['category']??'')?:null,trim($_POST['unit']??'pcs')?:'pcs',max(0,(int)($_POST['quantity']??0)),max(0,(int)($_POST['min_quantity']??0)),trim($_POST['location']??'')?:null,trim($_POST['notes']??'')?:null]);flash('Barang berhasil ditambahkan.');}elseif($action==='movement'){$id=(int)($_POST['item_id']??0);$type=$_POST['movement_type']??'Masuk';$qty=(int)($_POST['quantity']??0);if($id<1||$qty<1||!in_array($type,['Masuk','Keluar'],true))throw new RuntimeException();$pdo->beginTransaction();$q=$pdo->prepare('SELECT quantity FROM inventory_items WHERE id=? FOR UPDATE');$q->execute([$id]);$current=$q->fetchColumn();if($current===false)throw new RuntimeException();if($type==='Keluar'&&$qty>(int)$current)throw new RuntimeException();$new=$type==='Masuk'?(int)$current+$qty:(int)$current-$qty;$pdo->prepare('UPDATE inventory_items SET quantity=? WHERE id=?')->execute([$new,$id]);$pdo->prepare('INSERT INTO inventory_movements(item_id,movement_type,quantity,movement_date,notes,created_by) VALUES(?,?,?,?,?,?)')->execute([$id,$type,$qty,$_POST['movement_date']?:date('Y-m-d'),trim($_POST['movement_notes']??'')?:null,$_SESSION['user']['id']]);$pdo->commit();flash('Pergerakan stok berhasil dicatat.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Data tidak dapat disimpan. Pastikan jumlah barang keluar tidak melebihi stok.');}header('Location: inventory.php');exit;}
$items=$pdo->query('SELECT * FROM inventory_items ORDER BY name')->fetchAll();$low=(int)$pdo->query('SELECT COUNT(*) FROM inventory_items WHERE quantity<=min_quantity')->fetchColumn();require __DIR__.'/includes/header.php';show_flash();
?>
<section class="cards"><article class="stat"><div class="stat-label">Jenis Barang</div><div class="stat-value"><?=count($items)?></div></article><article class="stat"><div class="stat-label">Stok Menipis</div><div class="stat-value"><?=$low?></div></article></section>
<section class="panel"><div class="panel-head"><h3>Tambah Barang</h3></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="new"><div class="form-grid"><div class="field"><label>Kode barang</label><input name="item_code"></div><div class="field"><label>Nama barang *</label><input name="name" required></div><div class="field"><label>Kategori</label><input name="category"></div><div class="field"><label>Satuan</label><input name="unit" value="pcs"></div><div class="field"><label>Stok awal</label><input type="number" min="0" name="quantity" value="0"></div><div class="field"><label>Batas stok minimum</label><input type="number" min="0" name="min_quantity" value="0"></div><div class="field"><label>Lokasi penyimpanan</label><input name="location"></div><div class="field"><label>Catatan</label><input name="notes"></div></div><div class="form-actions"><button class="btn">Simpan Barang</button></div></form></section>
<section class="panel"><div class="panel-head"><h3>Catat Barang Masuk/Keluar</h3></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="movement"><div class="form-grid"><div class="field"><label>Barang</label><select name="item_id" required><?php foreach($items as $i):?><option value="<?=$i['id']?>"><?=e($i['name'])?> — stok <?=$i['quantity']?></option><?php endforeach;?></select></div><div class="field"><label>Jenis pergerakan</label><select name="movement_type"><option>Masuk</option><option>Keluar</option></select></div><div class="field"><label>Jumlah</label><input type="number" min="1" name="quantity" required></div><div class="field"><label>Tanggal</label><input type="date" name="movement_date" value="<?=date('Y-m-d')?>" required></div><div class="field full"><label>Catatan</label><input name="movement_notes"></div></div><div class="form-actions"><button class="btn">Catat Pergerakan</button></div></form></section>
<section class="panel"><div class="panel-head"><h3>Daftar Stok Barang</h3></div><table><thead><tr><th>Kode</th><th>Nama Barang</th><th>Kategori</th><th>Stok</th><th>Minimum</th><th>Lokasi</th><th>Status</th></tr></thead><tbody><?php if(!$items):?><tr><td colspan="7" class="empty">Belum ada barang.</td></tr><?php else:foreach($items as $i):?><tr><td><?=e($i['item_code']?:'-')?></td><td><?=e($i['name'])?></td><td><?=e($i['category']?:'-')?></td><td><?=number_format((int)$i['quantity'])?> <?=e($i['unit'])?></td><td><?=$i['min_quantity']?></td><td><?=e($i['location']?:'-')?></td><td><?=$i['quantity']<=$i['min_quantity']?'<strong style="color:#b45309">Stok menipis</strong>':'Aman'?></td></tr><?php endforeach;endif;?></tbody></table></section>
<?php require __DIR__.'/includes/footer.php';?>
